def _nav(active: str, include_sections: bool = True) -> str:
    items=[("overview","index.html","总览"),("workspace","workspace.html","工作区"),("metrics","metrics.html","二次指标"),("labels","labels.html","视频分类"),("discovery","discovery.html","博主发现"),("sync","sync.html","数据更新"),("ai","ai.html","AI 助手")]
    parts=[]
    for k,href,name in items:
        parts.append(f'<a class="{"active" if k==active else ""}" href="{href}">{name}</a>')
        if include_sections and k==active and SECTION_NAV.get(k):
            parts.append('<div class="subnav">'+''.join(f'<a data-section-nav="{anchor}" href="#{anchor}">{label}</a>' for anchor,label in SECTION_NAV[k])+'</div>')
    return f'<div class="side"><div class="brand">YouTube Creator Intelligence Hub<br><span class="version">v{__version__}</span></div><div class="nav">' + ''.join(parts) + '</div></div>'


def _page(title: str, active: str, body: str, base: str = "") -> str:
    nav = _nav(active, include_sections=not bool(base))
    if base:
        for name in ("index.html","workspace.html","metrics.html","labels.html","discovery.html","sync.html","ai.html"):
            nav=nav.replace(f'href="{name}"',f'href="{base}{name}"')
    asset_base=f"{base}assets/" if base else "assets/"
    section_script=f'<script src="{asset_base}section_nav.js"></script>' if (not base and SECTION_NAV.get(active)) else ''
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · YouTube Creator Intelligence Hub</title><style>{CSS}</style></head><body><div class="shell">{nav}<main class="main"><div id="runtimeStatus" class="runtime-status runtime-static"><b>正在检测运行模式…</b></div>{body}<div class="footer">YouTube Creator Intelligence Hub · 数据存储于本地 SQLite · v{__version__}</div></main></div><script src="{asset_base}export_tools.js"></script><script src="{asset_base}runtime_status.js"></script><script src="{asset_base}job_progress.js"></script><script src="{asset_base}product_ui.js"></script><script src="{asset_base}saved_views.js"></script>{section_script}</body></html>'''


def _sparkline(points: list[int | None]) -> str:
    nums=[x for x in points if isinstance(x,(int,float))]
    if len(nums)<2:return '<span class="small">—</span>'
    lo,hi=min(nums),max(nums);span=max(1,hi-lo);w,h=130,32;coords=[]
    for i,v in enumerate(nums):
        x=1+(w-2)*i/max(1,len(nums)-1);y=1+(h-2)*(1-(v-lo)/span);coords.append(f"{x:.1f},{y:.1f}")
    return f'<svg class="spark" viewBox="0 0 {w} {h}"><polyline fill="none" stroke="currentColor" stroke-width="1.8" points="{" ".join(coords)}"/></svg>'


def _page_size_controls(prefix: str) -> str:
    return f'<span class="small">每页</span><input id="{prefix}PageSize" class="input" type="number" min="1" max="5000" value="30" style="min-width:72px;width:82px"><button class="btn" id="{prefix}PageSizeConfirm">确定</button><span class="small">条</span>'

def _pager(prefix: str) -> str:
    return f'<div class="pager"><button class="btn" id="{prefix}First">第一页</button><button class="btn" id="{prefix}Prev">上一页</button><span id="{prefix}PageButtons" class="inline"></span><button class="btn" id="{prefix}Next">下一页</button><button class="btn" id="{prefix}Last">最后一页</button><span class="small">跳转到</span><input id="{prefix}PageInput" class="input" type="number" min="1" value="1"><button class="btn" id="{prefix}Jump">跳转</button><span id="{prefix}PageInfo" class="small"></span></div>'


def _creator_rows(conn) -> list[dict[str, Any]]:
    sql="""
    WITH va AS (
      SELECT v.channel_id,
             MAX(v.published_at) AS latest_upload,
             MAX(CASE WHEN COALESCE(l.human_role,s.suggested_role,'pending')='ugphone' THEN v.published_at END) AS latest_ugphone_upload,
             COUNT(*) AS stored_videos,
             SUM(CASE WHEN COALESCE(l.human_role,s.suggested_role,'pending')='ugphone' THEN 1 ELSE 0 END) AS identified_ugphone,
             SUM(CASE WHEN COALESCE(l.human_role,s.suggested_role,'pending')='competitor' THEN 1 ELSE 0 END) AS identified_competitor,
             SUM(CASE WHEN COALESCE(l.human_role,s.suggested_role,'pending')='daily' THEN 1 ELSE 0 END) AS identified_daily,
             SUM(CASE WHEN instr(lower(COALESCE(l.brands_json,s.brands_json,'')),'ldcloud')>0 THEN 1 ELSE 0 END) AS ldcloud_videos,
             SUM(CASE WHEN instr(lower(COALESCE(l.brands_json,s.brands_json,'')),'redfinger')>0 THEN 1 ELSE 0 END) AS redfinger_videos,
             SUM(CASE WHEN instr(lower(COALESCE(l.brands_json,s.brands_json,'')),'vsphone')>0 THEN 1 ELSE 0 END) AS vsphone_videos,
             SUM(CASE WHEN l.video_id IS NOT NULL THEN 1 ELSE 0 END) AS manual_corrections
      FROM videos v LEFT JOIN label_suggestions s ON s.video_id=v.video_id LEFT JOIN video_labels l ON l.video_id=v.video_id
      GROUP BY v.channel_id
    )
    , bm_latest_at AS (
      SELECT channel_id,metric_key,MAX(captured_at) AS captured_at
      FROM creator_business_metrics GROUP BY channel_id,metric_key
    )
    , bm AS (
      SELECT m.channel_id,
             SUM(CASE WHEN m.metric_key='gmv' THEN m.metric_value END) AS gmv_total,
             SUM(CASE WHEN m.metric_key='new_users' THEN m.metric_value END) AS new_users_total,
             MAX(CASE WHEN m.metric_key='gmv' THEN m.captured_at END) AS gmv_snapshot_at,
             MAX(CASE WHEN m.metric_key='new_users' THEN m.captured_at END) AS new_users_snapshot_at
      FROM creator_business_metrics m JOIN bm_latest_at x ON x.channel_id=m.channel_id AND x.metric_key=m.metric_key AND x.captured_at=m.captured_at
      GROUP BY m.channel_id
    )
    , bm_hist AS (
      SELECT channel_id,COUNT(*) AS business_metric_count,MAX(captured_at) AS business_metric_updated_at
      FROM creator_business_metrics GROUP BY channel_id
    )
    SELECT c.*,COALESCE(va.latest_upload,'') latest_upload,COALESCE(va.latest_ugphone_upload,'') latest_ugphone_upload,COALESCE(va.stored_videos,0) stored_videos,
           COALESCE(va.identified_ugphone,0) identified_ugphone,COALESCE(va.identified_competitor,0) identified_competitor,
           COALESCE(va.identified_daily,0) identified_daily,COALESCE(va.ldcloud_videos,0) ldcloud_videos,
           COALESCE(va.redfinger_videos,0) redfinger_videos,COALESCE(va.vsphone_videos,0) vsphone_videos,
           COALESCE(va.manual_corrections,0) manual_corrections,ds.first_seen_at AS discovery_first_seen_at,ds.last_seen_at AS discovery_data_at,COALESCE(ds.discovery_run_count,0) AS discovery_run_count,
           bm.gmv_total AS gmv_total,bm.new_users_total AS new_users_total,COALESCE(bh.business_metric_count,0) AS business_metric_count,bh.business_metric_updated_at,'USD' AS gmv_currency,bm.gmv_snapshot_at,bm.new_users_snapshot_at
    FROM creators c LEFT JOIN va ON va.channel_id=c.channel_id LEFT JOIN creator_discovery_summary ds ON ds.channel_id=c.channel_id LEFT JOIN bm ON bm.channel_id=c.channel_id LEFT JOIN bm_hist bh ON bh.channel_id=c.channel_id
    ORDER BY c.monitoring_enabled DESC,COALESCE(c.last_synced_at,c.discovered_at) DESC
    """
    return [dict(r) for r in conn.execute(sql).fetchall()]


def _enrich_creator_status(creators:list[dict[str,Any]], settings:dict[str,Any])->list[dict[str,Any]]:
    for c in creators:
        c['monitor_data_fresh']=1 if monitoring_data_fresh(
            settings, priority=c.get('priority'), last_synced_at=c.get('last_synced_at')
        ) else 0
        c['suspected_inactive_partner']=1 if suspected_inactive_partner(
            settings, monitoring_enabled=c.get('monitoring_enabled'), priority=c.get('priority'),
            last_synced_at=c.get('last_synced_at'), ugphone_video_count=c.get('identified_ugphone'),
            latest_ugphone_upload=c.get('latest_ugphone_upload'), inactive_days=30
        ) else 0
    return creators


def dashboard_stats_payload(db_path:str|Path)->dict[str,Any]:
    """Lightweight current counts for the interactive Dashboard; never rebuilds HTML."""
    with connect(db_path) as conn:
        workspace_ctx=active_workspace_context(conn)
        active_workspace=workspace_ctx.get("workspace") or {}
        workspace_name=str(active_workspace.get("name") or "General Creator Intelligence")
        workspace_meta=active_workspace.get("metadata") or {}
        cloud_compat=workspace_meta.get("compatibility_profile")=="cloud_phone_v1"
        stats={
          'creators':conn.execute('SELECT COUNT(*) FROM creators').fetchone()[0],
          'monitored':conn.execute('SELECT COUNT(*) FROM creators WHERE monitoring_enabled=1').fetchone()[0],
          'videos':conn.execute('SELECT COUNT(*) FROM videos').fetchone()[0],
          'snapshots':conn.execute('SELECT COUNT(*) FROM video_snapshots').fetchone()[0],
          'classified':conn.execute('SELECT COUNT(*) FROM label_suggestions').fetchone()[0],
          'review':conn.execute("""SELECT COUNT(*) FROM label_suggestions s LEFT JOIN video_labels l ON l.video_id=s.video_id WHERE l.video_id IS NULL AND (s.suggested_role='pending' OR s.confidence='review')""").fetchone()[0],
          'manual_corrections':conn.execute('SELECT COUNT(*) FROM video_labels').fetchone()[0],
        }
    return stats


def creator_facts_payload(db_path:str|Path, settings:dict[str,Any])->dict[str,Any]:
    """Current Creator facts for live interactive refresh, without Dashboard regeneration."""
    with connect(db_path) as conn:
        creators=_enrich_creator_status(_creator_rows(conn),settings)
        return build_creator_facts(creators,conn)


def metric_base_payload(db_path:str|Path, settings:dict[str,Any])->dict[str,Any]:
    """Current secondary-metric cube payload for interactive refresh, without HTML regeneration."""
    with connect(db_path) as conn:
        creators=_enrich_creator_status(_creator_rows(conn),settings)
        return build_metric_base(conn,creators)



def _dashboard_elapsed(started:float)->str:
    sec=max(0,int(time.perf_counter()-started))
    return f"{sec//60:02d}:{sec%60:02d}"


def _creator_detail_fingerprint(c:dict[str,Any], tags:list[str])->str:
    fields=(
        "channel_id","channel_title","handle","thumbnail_url","subscriber_count","channel_view_count",
        "channel_video_count","stored_videos","latest_upload","last_synced_at","channel_data_at",
        "video_metrics_at","classification_data_at","business_metric_updated_at","gmv_total",
        "new_users_total","gmv_snapshot_at","new_users_snapshot_at","contact_scraped_at",
    )
    payload={k:c.get(k) for k in fields}
    payload["tags"]=tags
    payload["dashboard_version"]=__version__
    return hashlib.sha256(json.dumps(payload,ensure_ascii=False,sort_keys=True,default=str).encode("utf-8")).hexdigest()


def _load_detail_sources(conn):
    """Load video rows and Creator tags once for the whole Dashboard build."""
    videos_by_creator:dict[str,list[dict[str,Any]]]=defaultdict(list)
    rows=conn.execute("""SELECT v.*,s.suggested_role,s.brands_json sbrands,s.confidence,s.evidence_json,
                               l.human_role,l.brands_json hbrands,l.labeled_by,l.labeled_at
                        FROM videos v
                        LEFT JOIN label_suggestions s ON s.video_id=v.video_id
                        LEFT JOIN video_labels l ON l.video_id=v.video_id
                        ORDER BY v.channel_id,COALESCE(v.current_views,0) DESC,v.published_at DESC""").fetchall()
    for rr in rows:
        r=dict(rr)
        videos_by_creator[str(r["channel_id"])].append(r)

    tags_by_creator:dict[str,list[str]]=defaultdict(list)
    for r in conn.execute("SELECT channel_id,tag FROM creator_tags ORDER BY channel_id,tag").fetchall():
        tags_by_creator[str(r["channel_id"])].append(str(r["tag"]))
    return videos_by_creator,tags_by_creator,len(rows)


def _load_snapshot_chunk(conn, channel_ids:list[str], snap_limit:int)->dict[str,list[int|None]]:
    if not channel_ids:
        return {}
    placeholders=",".join("?" for _ in channel_ids)
    sql=f"""WITH selected AS (
               SELECT video_id FROM videos WHERE channel_id IN ({placeholders})
             ),
             ranked AS (
               SELECT vs.video_id,vs.views,vs.captured_at,
                      ROW_NUMBER() OVER(PARTITION BY vs.video_id ORDER BY vs.captured_at DESC) rn
               FROM video_snapshots vs JOIN selected x ON x.video_id=vs.video_id
             )
             SELECT video_id,views FROM ranked WHERE rn<=? ORDER BY video_id,rn DESC"""
    rows=conn.execute(sql,tuple(channel_ids)+ (snap_limit,)).fetchall()
    out:dict[str,list[int|None]]={}
    for r in rows:
        out.setdefault(str(r["video_id"]),[]).append(r["views"])
    return out

def build_dashboard(db_path: str | Path, output_dir: str | Path, settings: dict[str, Any]) -> dict[str, Any]:
    build_started=time.perf_counter()
    def log(stage:int,message:str):
        print(f"[Dashboard {stage}/8] {message} · elapsed {_dashboard_elapsed(build_started)}",flush=True)
    out=Path(output_dir);creators_dir=out/'creators';creators_dir.mkdir(parents=True,exist_ok=True);limits=settings.get('dashboard',{});collection=settings.get('collection',{});full_history_limit=min(int(collection.get('max_videos_per_creator',10000)),int(collection.get('max_playlist_pages_full',200))*int(collection.get('playlist_page_size',50)))
    with connect(db_path) as conn:
        log(1,"Loading database facts and active Workspace")
        workspace_ctx=active_workspace_context(conn)
        active_workspace=workspace_ctx.get("workspace") or {}
        workspace_name=str(active_workspace.get("name") or "General Creator Intelligence")
        stats={
          'creators':conn.execute('SELECT COUNT(*) FROM creators').fetchone()[0],
          'monitored':conn.execute('SELECT COUNT(*) FROM creators WHERE monitoring_enabled=1').fetchone()[0],
          'videos':conn.execute('SELECT COUNT(*) FROM videos').fetchone()[0],
          'snapshots':conn.execute('SELECT COUNT(*) FROM video_snapshots').fetchone()[0],
          'classified':conn.execute('SELECT COUNT(*) FROM label_suggestions').fetchone()[0],
          'review':conn.execute("""SELECT COUNT(*) FROM label_suggestions s LEFT JOIN video_labels l ON l.video_id=s.video_id WHERE l.video_id IS NULL AND (s.suggested_role='pending' OR s.confidence='review')""").fetchone()[0],
          'manual_corrections':conn.execute('SELECT COUNT(*) FROM video_labels').fetchone()[0],
        }
        creators=_enrich_creator_status(_creator_rows(conn),settings)
        last_sync=dict(conn.execute('SELECT * FROM sync_runs ORDER BY id DESC LIMIT 1').fetchone() or {})
        workspace_id=str(active_workspace.get("id") or "")
        relationship_labels=defaultdict(list)
        if workspace_id:
            for rel in conn.execute("""SELECT r.channel_id,r.relationship_type,r.status,b.display_name
                                      FROM creator_relationships r
                                      LEFT JOIN workspace_brands b ON b.id=r.brand_id
                                      WHERE r.workspace_id=?
                                      ORDER BY r.channel_id,b.display_name,r.relationship_type,r.status""",(workspace_id,)).fetchall():
                bits=[str(rel["display_name"] or "").strip(),str(rel["relationship_type"] or "").strip(),str(rel["status"] or "").strip()]
                label=" · ".join(x for x in bits if x)
                if label and label not in relationship_labels[str(rel["channel_id"])]: relationship_labels[str(rel["channel_id"])].append(label)
        workspace_brand_choices=[(str(b.get("key") or ""),str(b.get("display_name") or b.get("key") or "")) for b in workspace_ctx.get("brands") or [] if b.get("key")]

        rows=[]
        for c in creators:
            fn=safe_filename(c['channel_id'])+'.html';priority=PRIORITY_NAMES.get(c.get('priority'),c.get('priority') or '—')
            country=c.get('country_resolved') or c.get('country_api') or '—'
            identity=list(relationship_labels.get(str(c['channel_id']),[]))
            search=(c.get('channel_title') or '')+' '+(c.get('handle') or '')+' '+country+' '+c['channel_id']+' '+' '.join(identity)
            tags=('<div class="identity-stack">'+''.join('<span class="pill identity-partnered">'+esc(x)+'</span>' for x in identity)+'</div>') if identity else '<span class="small">—</span>'
            channel_url=c.get('channel_url') or f"https://www.youtube.com/channel/{c['channel_id']}"
            policy=(settings.get('refresh_policy') or {}).get(c.get('priority') or 'normal',{})
            cadence=policy.get('new_video_hours') or policy.get('metric_hours') or '—'
            mon='<span class="pill monitor-on">监控中</span>' if c.get('monitoring_enabled') else '<span class="pill monitor-off">未监控</span>'
            biz_count=int(c.get('business_metric_count') or 0)
            biz_html=(f'<div><b>商业指标记录 {biz_count} 条</b></div><div class="small">最近更新 {esc(str(c.get("business_metric_updated_at") or "—")[:19])}</div>' if biz_count else '<span class="small">当前 Workspace 尚无商业指标记录</span>')
            rows.append(f'''<tr data-cid="{esc(c['channel_id'])}" data-search="{esc(search)}"><td><input type="checkbox" class="ov-select creator-select" value="{esc(c['channel_id'])}"></td><td class="entity-cell"><a class="link-ext" target="_blank" rel="noopener" href="{esc(channel_url)}"><b>{esc(c.get('channel_title') or c['channel_id'])}</b></a><div class="small mono">{esc(c.get('handle') or c['channel_id'])}</div><div class="small"><button class="btn" data-inspect-creator="{esc(c['channel_id'])}" data-creator-title="{esc(c.get('channel_title') or c['channel_id'])}" data-priority="{esc(priority)}" data-monitoring="{'监控中' if c.get('monitoring_enabled') else '未监控'}" data-sync-status="{esc(c.get('last_sync_status') or '—')}" data-last-sync="{esc(c.get('last_synced_at') or '—')}" data-next-sync="{esc(c.get('next_sync_at') or '—')}" data-next-retry="{esc(c.get('next_retry_at') or '—')}" data-failures="{int(c.get('consecutive_sync_failures') or 0)}" data-channel-data="{esc(c.get('channel_data_at') or '—')}" data-video-metrics="{esc(c.get('video_metrics_at') or '—')}" data-classification-data="{esc(c.get('classification_data_at') or '—')}" data-contact-data="{esc(c.get('contact_scraped_at') or '—')}">详情</button></div></td><td>{esc(country)}</td><td>{fmt_int(c.get('subscriber_count'))}</td><td>{fmt_int(c.get('channel_view_count'))}</td><td>{fmt_int(c.get('stored_videos'))}</td><td class="identity-cell">{tags}</td><td class="metric-cell">{biz_html}</td><td><div class="status-summary"><span class="pill priority-label">{esc(priority)}优先级</span>{mon}</div></td></tr>''')
        body=f'''<div class="title"><div><h1>YouTube Creator Intelligence Hub</h1><div class="sub">当前 Workspace：{esc(workspace_name)} · Creator / Video 全局事实 + Workspace Intelligence</div></div><div class="small">最近同步：{esc(last_sync.get('finished_at') or last_sync.get('started_at') or '—')}</div></div>
        <div class="grid two anchor-section" id="overview-summary"><div class="card"><div class="metric" id="overviewMonitoredCount">{stats['monitored']:,}</div><div class="label">监控中的博主</div></div><div class="card"><div class="metric" id="overviewVideoCount">{stats['videos']:,}</div><div class="label">已存视频</div></div></div>
        <div class="section anchor-section" id="overview-identity"><div class="note"><b>关系口径：</b>身份与关系只来自当前 Workspace 的 Creator Relationship；Core 不根据特定客户、品牌或行业自动定义“已合作 / 未合作”。品牌内容语义由 Workspace Taxonomy 管理。<br><b>监控口径：</b>“监控中”表示该博主进入批量同步队列；“高 / 普通 / 低 / 归档优先级”分别按配置周期判断是否到期，未到期会在批量同步时跳过。</div></div>
        <div class="section anchor-section" id="overview-library"><div class="inline spread"><h2>博主库</h2><div class="saved-view-bar"><select id="ovSavedView" class="select"><option value="">已保存视图…</option></select><button class="btn" id="ovSaveView">保存当前视图</button><button class="btn danger" id="ovDeleteView">删除视图</button><span id="ovSavedViewStatus" class="small"></span><button class="btn" id="ovExport">导出 XLSX</button></div></div><div class="actionbar"><label class="small"><input type="checkbox" id="ovSelectVisible"> 勾选当前页</label><button class="btn" id="ovSelectAllResults">全选结果</button><button class="btn" id="ovClearSelection">清除选择</button><b id="ovSelectionStatus" class="small">已选择 0 条</b><details class="action-menu"><summary class="btn">监控 ▾</summary><div class="action-menu-panel"><button class="btn" data-ov-batch="monitor_on">开启监控</button><button class="btn" data-ov-batch="monitor_off">关闭监控</button><button class="btn" data-ov-batch="resume_sync">恢复异常同步</button></div></details><details class="action-menu"><summary class="btn">优先级 ▾</summary><div class="action-menu-panel"><select id="ovBatchPriority" class="select"><option value="normal">普通优先级</option><option value="high">高优先级</option><option value="low">低优先级</option><option value="archive">归档</option></select><button class="btn primary" data-ov-batch="priority">应用优先级</button></div></details><details class="action-menu"><summary class="btn">标签 ▾</summary><div class="action-menu-panel"><input id="ovBatchTag" class="input" placeholder="标签名称"><button class="btn primary" data-ov-batch="tag">添加标签</button></div></details><span id="ovBatchStatus" class="small"></span></div><div class="toolbar"><input id="q" class="input" placeholder="搜索博主 / Handle / Channel ID / 国家 / 身份标签"></div><div class="builder-panel"><div id="ovFilterConditions"></div><div class="inline"><button class="btn" id="ovAddFilter">添加筛选条件</button><button class="btn primary" id="ovApplyFilter">应用筛选</button><button class="btn" id="ovClearFilter">清除</button><span class="small">博主标签为布尔标签，可直接选择“存在 / 不存在”，不填写数字阈值。</span><span id="ovFilterStatus" class="small"></span></div></div><div class="toolbar section"><span class="small">排序</span><select id="ovSort" class="select"><option value="subscriber_count" selected>订阅数</option><option value="channel_title">博主名称</option><option value="country">国家</option><option value="channel_view_count">频道累计播放量</option><option value="stored_videos">已存视频数</option><option value="latest_upload">最近发布</option></select><select id="ovSortDir" class="select"><option value="desc" selected>降序</option><option value="asc">升序</option></select>{_page_size_controls("ov")}<span id="ovSummary" class="table-summary"></span></div><div class="table-wrap"><table id="overviewTable"><thead><tr id="overviewHead"><th data-field="selection">选择</th><th data-field="channel_title">博主</th><th data-field="country geography">国家</th><th data-field="subscriber_count">订阅数</th><th data-field="channel_view_count">频道累计播放量</th><th data-field="stored_videos">已存视频数</th><th data-field="identity creator_label">Workspace 关系</th><th data-field="business_metrics">商业表现</th><th data-field="monitoring_enabled priority last_sync_status">状态</th></tr></thead><tbody id="rows">{''.join(rows)}</tbody></table></div>{_pager("ov")}</div>
        <script src="assets/creator_facts.js"></script><script src="assets/metric_base.js"></script><script src="assets/metrics_config.js"></script><script src="assets/geography.js"></script><script src="assets/table_tools.js"></script><script src="assets/field_registry.js"></script><script src="assets/overview_filters.js"></script>'''
        (out/'index.html').write_text(_page('总览','overview',body),encoding='utf-8')

        log(2,f"Overview written; preparing Creator detail source rows for {len(creators):,} creators")
        snap_limit=int(limits.get('snapshot_points_per_video',60))
        videos_by_creator,tags_by_creator,detail_video_rows=_load_detail_sources(conn)
        log(3,f"Loaded {detail_video_rows:,} video rows and Creator tags in bulk")

        assets_dir=out/'assets'
        assets_dir.mkdir(parents=True,exist_ok=True)
        state_path=assets_dir/'dashboard_build_state.json'
        try:
            previous_state=json.loads(state_path.read_text(encoding='utf-8')) if state_path.exists() else {}
        except Exception:
            previous_state={}
        previous_fingerprints=previous_state.get('creator_detail_fingerprints') if previous_state.get('version')==__version__ else {}
        if not isinstance(previous_fingerprints,dict): previous_fingerprints={}
        next_fingerprints={}
        built_pages=0
        cached_pages=0
        total_creators=len(creators)
        chunk_size=32

        for batch_start in range(0,total_creators,chunk_size):
            batch=creators[batch_start:batch_start+chunk_size]
            build_batch=[]
            for c in batch:
                cid=str(c['channel_id'])
                tags=tags_by_creator.get(cid,[])
                fp=_creator_detail_fingerprint(c,tags)
                next_fingerprints[cid]=fp
                page=creators_dir/(safe_filename(cid)+'.html')
                if page.exists() and previous_fingerprints.get(cid)==fp:
                    cached_pages+=1
                else:
                    build_batch.append(c)

            # Snapshot histories are loaded once per chunk, not once per Creator.
            snap_map=_load_snapshot_chunk(conn,[str(c['channel_id']) for c in build_batch],snap_limit) if build_batch else {}

            for c in build_batch:
                cid=str(c['channel_id'])
                videos=videos_by_creator.get(cid,[])
                tags=tags_by_creator.get(cid,[])
                vrows=[]
                for v in videos:
                    human=v.get('human_role');system=v.get('suggested_role') or 'pending';role=human or system
                    brands=json_load(v.get('hbrands') if human else v.get('sbrands'),[]);confidence=CONF_NAMES.get(v.get('confidence'),v.get('confidence') or '—')
                    label=f'<span class="pill {esc(role)}">{esc(_role_name(role))}</span>'
                    if human:label+=f'<div class="small">人工修正 · 原系统识别：{esc(_role_name(system))}</div>'
                    else:label+=f'<div class="small">系统识别 · 置信度：{esc(confidence)}</div>'
                    search=(v.get('title') or '')+' '+v['video_id']+' '+role+' '+' '.join(brands)
                    brand_text=' '.join(str(x).lower() for x in brands)
                    vrows.append(f'''<tr data-search="{esc(search)}" data-role="{esc(role)}" data-brands="{esc(brand_text)}" data-views="{int(v.get('current_views') or 0)}" data-likes="{int(v.get('current_likes') or 0)}" data-comments="{int(v.get('current_comments') or 0)}" data-published="{esc(v.get('published_at') or '')}" data-title="{esc(v.get('title') or '')}"><td><a target="_blank" rel="noopener" href="https://www.youtube.com/watch?v={esc(v['video_id'])}"><b>{esc(v.get('title') or v['video_id'])}</b></a><div class="small mono">{esc(v['video_id'])}</div></td><td>{esc((v.get('published_at') or '')[:10] or '—')}</td><td>{fmt_int(v.get('current_views'))}<div>{_sparkline(list(reversed(snap_map.get(v['video_id'],[]))))}</div></td><td>{fmt_int(v.get('current_likes'))}</td><td>{fmt_int(v.get('current_comments'))}</td><td>{label}<div class="small">{esc(', '.join(brands) or '—')}</div></td><td><div class="small">{esc(v.get('last_metric_at') or '—')}</div></td></tr>''')
                facts=f'''<div class="facts"><div class="card fact"><span class="small">订阅数</span><b>{fmt_int(c.get('subscriber_count'))}</b></div><div class="card fact"><span class="small">频道累计播放量</span><b>{fmt_int(c.get('channel_view_count'))}</b></div><div class="card fact"><span class="small">YouTube视频总数</span><b>{fmt_int(c.get('channel_video_count'))}</b></div><div class="card fact"><span class="small">国家（API）</span><b>{esc(c.get('country_api') or '—')}</b></div><div class="card fact"><span class="small">商业指标记录</span><b>{int(c.get('business_metric_count') or 0)}</b><span class="small">按当前 Workspace 定义解释</span></div></div><div class="section note"><b>数据新鲜度：</b>频道 {esc(c.get('channel_data_at') or '—')} · 视频指标 {esc(c.get('video_metrics_at') or '—')} · 分类 {esc(c.get('classification_data_at') or '—')} · 联系方式 {esc(c.get('contact_scraped_at') or '—')} · 商业数据 {esc(c.get('business_metric_updated_at') or '—')} · 发现 {esc(c.get('discovery_data_at') or '—')} · 完整同步 {esc(c.get('last_synced_at') or '—')}</div>'''
                cbody=f'''<div class="title"><div><a class="small" href="../index.html">← 返回博主库</a><div class="hero"><img class="avatar" src="{esc(c.get('thumbnail_url') or '')}"><div><h1><a class="link-ext" target="_blank" rel="noopener" href="{esc(c.get('channel_url') or ('https://www.youtube.com/channel/'+c['channel_id']))}">{esc(c.get('channel_title') or c['channel_id'])}</a></h1><div class="sub mono">{esc(c['channel_id'])} · {esc(c.get('handle') or '')}</div><div>{''.join('<span class="pill">'+esc(t)+'</span>' for t in tags)}</div></div></div></div><div class="small">最近同步<br>{esc(c.get('last_synced_at') or '—')}</div></div>{facts}<div class="section note ai-callout"><b>AI 可选增强：</b>Creator Brief 只读取本地事实并生成独立 AI 判断，不修改系统评分、标签或人工结果。<br><a class="link-ext" href="../ai.html?brief={esc(c['channel_id'])}#ai-brief">在 AI 助手中分析此博主</a></div><div class="section"><h2>视频 · 当前客观数据 + 有效分类（人工优先）</h2>
                <div class="toolbar"><input id="detailSearch" class="input" placeholder="搜索视频 / Video ID / 分类 / 品牌"><button class="btn" id="detailExport">导出 XLSX</button></div><div class="builder-panel"><div id="detailFilterConditions"></div><div class="inline"><button class="btn" id="detailAddFilter">添加筛选条件</button><button class="btn primary" id="detailApplyFilter">应用筛选</button><button class="btn" id="detailClearFilter">清除筛选</button></div></div>
                <div class="toolbar section"><span class="small">排序</span><select id="detailSort" class="select"><option value="views" selected>播放量</option><option value="published">发布时间</option><option value="likes">点赞数</option><option value="comments">评论数</option><option value="title">视频名称</option><option value="role">视频分类</option></select><select id="detailSortDir" class="select"><option value="desc" selected>降序</option><option value="asc">升序</option></select>{_page_size_controls("detail")}<span id="detailSummary" class="table-summary"></span></div>
                <div class="table-wrap"><table id="detailTable"><thead><tr><th data-field="title">视频</th><th data-field="published">发布时间</th><th data-field="views">播放量 / 历史</th><th data-field="likes">点赞数</th><th data-field="comments">评论数</th><th data-field="role brand">有效分类（人工优先）</th><th data-field="metric_time">指标抓取时间</th></tr></thead><tbody id="detailRows">{''.join(vrows)}</tbody></table></div>{_pager("detail")}</div><script src="../assets/table_tools.js"></script><script src="../assets/creator_detail.js"></script>'''
                (creators_dir/(safe_filename(c['channel_id'])+'.html')).write_text(_page(c.get('channel_title') or c['channel_id'],'overview',cbody,base='../'),encoding='utf-8')

                built_pages+=1

            done=min(batch_start+len(batch),total_creators)
            if done==total_creators or done%64==0:
                log(4,f"Creator pages {done:,}/{total_creators:,} · rebuilt {built_pages:,} · cache hit {cached_pages:,}")

        # Remove pages for Creators that no longer exist.
        valid_pages={safe_filename(str(c['channel_id']))+'.html' for c in creators}
        removed_pages=0
        for p in creators_dir.glob('*.html'):
            if p.name not in valid_pages:
                p.unlink()
                removed_pages+=1

        state_path.write_text(json.dumps({
            'version':__version__,
            'creator_detail_fingerprints':next_fingerprints,
            'updated_at':time.time(),
        },ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf-8')
        log(4,f"Creator detail stage complete · rebuilt {built_pages:,} · cached {cached_pages:,} · removed {removed_pages:,}")

        static_dir=Path(__file__).resolve().parent/'static'
        static_js=static_dir/'metrics_workspace.js'
        def metric_progress(stage,current,total,message):
            if total:
                suffix=f"{current:,}/{total:,}"
            else:
                suffix=""
            log(5,f"{stage}: {message} {suffix}".strip())
        metric_result=write_metric_assets(conn,out,creators,last_sync,static_js,progress=metric_progress)
        log(5,f"Metric assets complete · cubes {metric_result.get('cubes',0):,} · cache hit {bool(metric_result.get('metric_cache_hit'))}")
        assets=out/'assets'
        log(6,"Writing shared static assets and primary Workspace/Metric pages")
        geo_path=Path(__file__).resolve().parents[1]/'config'/'geography.json'
        geo_obj=json.loads(geo_path.read_text(encoding='utf-8'))
        (assets/'geography.js').write_text('window.CDH_GEOGRAPHY='+json.dumps(geo_obj,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
        qp_path=Path(__file__).resolve().parents[1]/'config'/'query_packs.json'
        qp_obj=json.loads(qp_path.read_text(encoding='utf-8'))
        (assets/'query_packs.js').write_text('window.CDH_QUERY_PACKS='+json.dumps(qp_obj,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
        (assets/'discovery.js').write_text((static_dir/'discovery.js').read_text(encoding='utf-8'),encoding='utf-8')
        (assets/'table_tools.js').write_text((static_dir/'table_tools.js').read_text(encoding='utf-8'),encoding='utf-8')
        (assets/'field_registry.js').write_text((static_dir/'field_registry.js').read_text(encoding='utf-8'),encoding='utf-8')
